const vATPosition = `-- name: VATPosition :one
SELECT
  COALESCE(sum(CASE WHEN kind = 'INVOICE' THEN total_cents ELSE -total_cents END), 0)::bigint AS sales_cents,
  COALESCE(sum(CASE WHEN kind = 'INVOICE' THEN tax_cents ELSE -tax_cents END), 0)::bigint AS output_vat_cents,
  count(*) FILTER (WHERE kind = 'INVOICE') AS invoices,
  count(*) FILTER (WHERE kind = 'CREDIT_NOTE') AS credit_notes
FROM invoices
WHERE org_id = $1 AND state = 'ACKED' AND acked_at >= $2 AND acked_at < $3
`

type VATPositionParams struct {
	OrgID     uuid.UUID
	AckedAt   *time.Time
	AckedAt_2 *time.Time
}

type VATPositionRow struct {
	SalesCents     int64
	OutputVatCents int64
	Invoices       int64
	CreditNotes    int64
}

func (q *Queries) VATPosition(ctx context.Context, arg VATPositionParams) (VATPositionRow, error) {
	row := q.db.QueryRow(ctx, vATPosition, arg.OrgID, arg.AckedAt, arg.AckedAt_2)
	var i VATPositionRow
	err := row.Scan(
		&i.SalesCents,
		&i.OutputVatCents,
		&i.Invoices,
		&i.CreditNotes,
	)
	return i, err
}
